+    let temp = tempfile::tempdir().unwrap();
+    let out = temp.path().join("DUODI20");
+    let jobs = [opening(-30.), opening(30.)];
+    let job = export_group_with_review(&jobs, &out, "DUODI20", 1.0).unwrap();
+    let names: Vec<_> = job
+        .files
+        .iter()
+        .map(|p| p.file_name().unwrap().to_str().unwrap().to_owned())
