+    // Each ISO enters its own left wall from inside its own opening.
+    for (n, wall) in [(1, "-42.50000"), (2, "17.50000")] {
+        let iso = std::fs::read_to_string(out.join(format!("DUODI20{n}.ISO"))).unwrap();
